WITH lines AS (SELECT id, host, log_ts, latency_ms, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, attr_value) SELECT CASE WHEN latency_ms >= 2249 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, k, SORT_ARRAY(COLLECT_SET(k)) AS k_list, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, COUNT(*) FILTER (WHERE host = 'h2') AS h2_rows, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, GROUPING_ID() AS gid FROM lines GROUP BY GROUPING SETS ((CASE WHEN latency_ms >= 2249 THEN 'HIGH' ELSE 'LOW' END, k), (CASE WHEN latency_ms >= 2249 THEN 'HIGH' ELSE 'LOW' END), ())
